assert.equal(state.orders.length,1);const order=state.orders[0];assert.equal(order.orderId,'16297733');assert.equal(order.phase,'semantic_mismatch');const economics=inspectNoAckAllEconomics(order.ack);assert.equal(economics.allState,'neutral');assert.equal(economics.ackNotional,'0.070000');
